BEGIN;
-- Test sessions are MFA-verified (aal2) unless a test clears this; admin authority requires it.
SELECT pg_catalog.set_config('request.jwt.claim', '{"aal":"aal2"}', true);
SELECT plan(29);
INSERT INTO auth.users(id,aud,role,email,raw_user_meta_data,created_at,updated_at) VALUES
('e2000000-0000-4000-8000-000000000001','authenticated','authenticated','coupon-admin@example.test','{}',now(),now()),
('e2000000-0000-4000-8000-000000000002','authenticated','authenticated','coupon-owner@example.test','{}',now(),now()),
('e2000000-0000-4000-8000-000000000003','authenticated','authenticated','coupon-other@example.test','{}',now(),now());
INSERT INTO public.user_roles(user_id,role,granted_by) VALUES('e2000000-0000-4000-8000-000000000001','admin','e2000000-0000-4000-8000-000000000001');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e2000000-0000-4000-8000-000000000001',true);
SELECT set_config('c.course',public.admin_save_course_content('coupon-check','en','Coupon course','Fixture','',50000,'','beginner',true)::text,true);
SELECT set_config('c.pct',public.admin_create_coupon('save20',20,NULL,NULL,NULL,NULL)::text,true);
SELECT set_config('c.flat',public.admin_create_coupon('FLAT100',NULL,10000,'coupon-check',1,NULL)::text,true);
SELECT public.admin_create_coupon('TOOBIG',NULL,999999,NULL,NULL,NULL);
SELECT public.admin_create_coupon('OFFLINE',10,NULL,NULL,NULL,NULL);
SELECT public.admin_set_coupon_active((SELECT id FROM public.coupons WHERE code='OFFLINE'),false);
SELECT is((SELECT code FROM public.coupons WHERE id=current_setting('c.pct')::uuid),'SAVE20','codes are normalized to upper case');
SELECT throws_ok($$SELECT public.admin_create_coupon('SAVE20',5,NULL,NULL,NULL,NULL)$$,'23505',NULL,'duplicate code rejected');
SELECT throws_ok($$SELECT public.admin_create_coupon('BOTH',5,100,NULL,NULL,NULL)$$,'22023',NULL,'exactly one discount kind required');
SELECT throws_ok($$SELECT public.admin_create_coupon('FREE',100,NULL,NULL,NULL,NULL)$$,'23514',NULL,'100 percent coupons rejected');
SELECT is((SELECT count(*)::int FROM public.admin_list_coupons()),4,'admin lists coupons');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.admin_audit_log WHERE target_type='coupon'),5,'coupon administration is audited');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e2000000-0000-4000-8000-000000000002',true);
SELECT throws_ok($$SELECT public.admin_create_coupon('LEARNER',10,NULL,NULL,NULL,NULL)$$,'42501',NULL,'learner cannot create coupons');
SELECT throws_ok($$SELECT * FROM public.admin_list_coupons()$$,'42501',NULL,'learner cannot list coupons');
SELECT throws_ok($$SELECT * FROM public.coupons$$,'42501',NULL,'coupon table is not exposed');
SELECT set_config('c.order',public.learner_create_order(current_setting('c.course')::uuid,'en')::text,true);
SELECT is((SELECT subtotal_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),50000::bigint,'subtotal snapshot stored');
SELECT is((public.learner_apply_coupon(current_setting('c.order')::uuid,'nope'))->>'reason','invalid','unknown code rejected');
SELECT is((public.learner_apply_coupon(current_setting('c.order')::uuid,'OFFLINE'))->>'reason','invalid','inactive code rejected');
SELECT is((public.learner_apply_coupon(current_setting('c.order')::uuid,'TOOBIG'))->>'reason','notApplicable','coupon cannot make a paid order free');
SELECT is((SELECT coupon_attempts FROM public.orders WHERE id=current_setting('c.order')::uuid),3::smallint,'rejected attempts are counted');
SELECT ok((public.learner_apply_coupon(current_setting('c.order')::uuid,' save20 '))->>'ok'='true','percentage coupon applies');
SELECT is((SELECT total_minor FROM public.orders WHERE id=current_setting('c.order')::uuid),40000::bigint,'server computes percentage discount');
SELECT ok((public.learner_apply_coupon(current_setting('c.order')::uuid,'FLAT100'))->>'ok'='true','course coupon replaces previous coupon');
SELECT is((SELECT discount_minor||':'||total_minor||':'||coupon_code FROM public.orders WHERE id=current_setting('c.order')::uuid),'10000:40000:FLAT100','fixed discount snapshot');
SELECT throws_ok($$UPDATE public.orders SET total_minor=1$$,'42501',NULL,'learner cannot write order totals');
SELECT throws_ok($$SELECT public.learner_set_order_billing(current_setting('c.order')::uuid,'A','EG','+201000000000')$$,'22023',NULL,'invalid billing rejected');
SELECT lives_ok($$SELECT public.learner_set_order_billing(current_setting('c.order')::uuid,'Learner Name','EG','+201000000000')$$,'owner saves billing snapshot');
SELECT set_config('request.jwt.claim.sub','e2000000-0000-4000-8000-000000000003',true);
SELECT throws_ok($$SELECT public.learner_apply_coupon(current_setting('c.order')::uuid,'SAVE20')$$,'P0002',NULL,'another account cannot change the order coupon');
SELECT throws_ok($$SELECT public.learner_set_order_billing(current_setting('c.order')::uuid,'Other','EG','+201000000001')$$,'P0002',NULL,'another account cannot change billing');
SELECT set_config('c.other',public.learner_create_order(current_setting('c.course')::uuid,'en')::text,true);
SELECT is((public.learner_apply_coupon(current_setting('c.other')::uuid,'FLAT100'))->>'reason','exhausted','pending order reserves the single redemption');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($SELECT public.commerce_bind_session(current_setting('c.order')::uuid,'0123456789abcdef01234568','https://payments.kashier.io/session/0123456789abcdef01234568?mode=test',50000)$,'23514',NULL,'session amount must match the current discounted total');
SELECT public.commerce_bind_session(current_setting('c.order')::uuid,'0123456789abcdef01234568','https://payments.kashier.io/session/0123456789abcdef01234568?mode=test',40000);
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','e2000000-0000-4000-8000-000000000002',true);
SELECT is((public.learner_apply_coupon(current_setting('c.order')::uuid,'SAVE20'))->>'reason','locked','coupon cannot change after the provider session is bound');
SELECT throws_ok($$SELECT public.learner_remove_coupon(current_setting('c.order')::uuid)$$,'55000',NULL,'coupon cannot be removed after the provider session is bound');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT public.commerce_confirm_order(current_setting('c.order')::uuid,'0123456789abcdef01234568','provider-coupon',40000,'EGP','paid','coupon-capture');
RESET ROLE;
SELECT is((SELECT status FROM public.orders WHERE id=current_setting('c.order')::uuid),'paid','discounted total settles');
SELECT ok(NOT has_function_privilege('anon','public.learner_apply_coupon(uuid,text)','EXECUTE') AND NOT has_function_privilege('authenticated','public.checkout_lock_editable_order(uuid)','EXECUTE'),'coupon functions are not exposed to anonymous callers and the lock helper is private');
SELECT * FROM finish();ROLLBACK;
